action.command:
cd /workspace && cat > /tmp/restorepw.php <<'PHP'
<?php
$pdo = new PDO('mysql:host=db;dbname=db', 'db', 'db');
$orig = trim(file_get_contents('/tmp/orig_pw.txt'));
$st = $pdo->prepare('UPDATE user SET password=:p WHERE id=1');
$st->execute([':p' => $orig]);
echo 'restored rows: ' . $st->rowCount() . PHP_EOL;
// verify
$r = $pdo->query("SELECT password FROM user WHERE id=1")->fetchColumn();
echo 'restored pw matches orig: ' . (hash_equals($orig, $r) ? 'YES' : 'NO') . PHP_EOL;
PHP
cp /tmp/restorepw.php /workspace/restorepw_tmp.php && chown dev:dev /workspace/restorepw_tmp.php && su - dev -c 'cd /workspace && export PATH=$HOME/.local/bin:$PATH && ddev exec php restorepw_tmp.php' 2>&1 | grep -v Xdebug; rm -f /workspace/setpw_tmp.php /workspace/restorepw_tmp.php; echo "temp files removed"; ls /workspace/*.php 2>/dev/null || echo "no stray php files in workspace root"

